<script setup>
import { onMounted, ref } from 'vue'
import ExcelJS from 'exceljs'
import { ElMessage } from 'element-plus'
import { confirmEmployeeImport, previewEmployeeImport } from '@/api/adminPhase2'
import { resetActivation } from '@/api/adminPhase2'
import { getUserList } from '@/api/platform'

const sourceRows=ref([]);const preview=ref(null);const created=ref([]);const accounts=ref([])
const headers=['employeeNo','name','phone','email','role','farmCode','plotCodes']
async function downloadTemplate(){const book=new ExcelJS.Workbook();const sheet=book.addWorksheet('员工导入');sheet.addRow(headers);sheet.addRow(['EMP-001','张三','13800000000','user@example.com','farmer','F001','P001,P002']);const data=await book.xlsx.writeBuffer();const url=URL.createObjectURL(new Blob([data]));const a=document.createElement('a');a.href=url;a.download='橙心如意员工导入模板.xlsx';a.click();URL.revokeObjectURL(url)}
async function readFile(file){const book=new ExcelJS.Workbook();await book.xlsx.load(await file.raw.arrayBuffer());const sheet=book.worksheets[0];const first=sheet.getRow(1).values.slice(1).map(String);sourceRows.value=[];sheet.eachRow((row,index)=>{if(index===1)return;const record={};first.forEach((key,i)=>record[key]=String(row.getCell(i+1).text||'').trim());record.plotCodes=record.plotCodes?record.plotCodes.split(/[,，]/).map(x=>x.trim()).filter(Boolean):[];if(Object.values(record).some(value=>Array.isArray(value)?value.length:Boolean(value)))sourceRows.value.push(record)});preview.value=await previewEmployeeImport(sourceRows.value);ElMessage.success(`已读取 ${sourceRows.value.length} 行`) }
async function confirm(){const result=await confirmEmployeeImport(sourceRows.value);created.value=result.users;ElMessage.success(`已导入 ${result.createdCount} 名员工`) }
async function resetCode(row){const result=await resetActivation(row.id);await ElMessage.alert(`新激活码：${result.activationCode}\n请安全地单独发送给员工，本窗口关闭后不再展示。`,'激活凭证已重置');accounts.value=await getUserList()}
onMounted(async()=>{accounts.value=await getUserList()})
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">员工管理</h1><p class="page-subtitle">Excel 仅负责读取；必须预校验通过后才会写入数据库。</p></div><div><el-button @click="downloadTemplate">下载模板</el-button><el-upload :auto-upload="false" :show-file-list="false" accept=".xlsx" class="upload" @change="readFile"><el-button type="primary">选择 Excel 并预校验</el-button></el-upload></div></div><section class="content-panel"><h2>员工账号</h2><el-table :data="accounts"><el-table-column prop="employeeNo" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column label="角色"><template #default="s">{{s.row.roleCodes?.join(', ')}}</template></el-table-column><el-table-column prop="activationStatus" label="激活状态"/><el-table-column label="授权范围"><template #default="s">{{[...(s.row.farmIds||[]),...(s.row.plotIds||[])].join(', ')}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="s"><el-button v-if="s.row.employeeNo" link type="primary" @click="resetCode(s.row)">重置激活凭证</el-button></template></el-table-column></el-table></section><el-alert v-if="preview" class="result" :title="`有效 ${preview.validCount} 行，错误 ${preview.invalidCount} 行`" :type="preview.invalidCount?'warning':'success'" show-icon :closable="false"/><section v-if="preview" class="content-panel result"><el-table :data="[...preview.invalidRows,...preview.validRows]"><el-table-column prop="rowNumber" label="行" width="60"/><el-table-column prop="employeeNo" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="role" label="角色"/><el-table-column prop="farmCode" label="农场"/><el-table-column label="地块"><template #default="s">{{s.row.plotCodes?.join(', ')}}</template></el-table-column><el-table-column label="校验结果" min-width="220"><template #default="s"><span :class="s.row.errorReasons?.length?'error':'success'">{{s.row.errorReasons?.join('；')||'通过'}}</span></template></el-table-column></el-table><div class="confirm"><el-button type="primary" :disabled="preview.invalidCount>0||!preview.validCount" @click="confirm">确认导入</el-button></div></section><section v-if="created.length" class="content-panel codes"><h2>激活凭证（仅本次显示）</h2><el-table :data="created"><el-table-column prop="employeeNo" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="activationCode" label="激活码"/></el-table></section></div></template>
<style scoped>.page-head>div:last-child{display:flex;gap:10px}.upload{display:inline-flex}.result,.codes{margin-top:18px}.error{color:#c64d3f}.success{color:#27845f}.confirm{display:flex;justify-content:flex-end;margin-top:18px}</style>
